export type GlassSlabLogoRenderer = {
  update: (tuning: GlassSlabLogoTuning) => void;
  setBackdrop: (backdrop: Backdrop | null) => void;
  replay: () => void;
  seek: (seconds: number) => void;
  pause: () => void;
  play: () => void;
